CREATE PROCEDURE [RedeemCodes_selectrow]
	@P_1 BigInt,
	@sync_scope_local_id Int,
	@sync_scope_restore_count Int
AS
BEGIN
SELECT [side].[Id], [base].[DbName], [base].[Codice], [base].[Azione], [base].[Valore], [base].[Bonus], [base].[Tickets], [base].[IdPromozione], [base].[IdCompleanno], [base].[IdContatto], [base].[MailDestinatario], [base].[CardLevel], [base].[Pin], [base].[ValidFrom], [base].[ValidTo], [base].[CreatedBy], [base].[CreatedAt], [base].[ReservedBy], [base].[ReservedAt], [base].[ReservedOnPost], [base].[ReservedOnDevice], [base].[ReservationExpiresAt], [base].[UsedBy], [base].[UsedAt], [base].[UsedOnPost], [base].[UsedOnDevice], [base].[Note], [base].[QRCode], [side].[sync_row_is_tombstone], [side].[local_update_peer_timestamp] as sync_row_timestamp, case when ([side].[update_scope_local_id] is null or [side].[update_scope_local_id] <> @sync_scope_local_id) then COALESCE([side].[restore_timestamp], [side].[local_update_peer_timestamp]) else [side].[scope_update_peer_timestamp] end as sync_update_peer_timestamp, case when ([side].[update_scope_local_id] is null or [side].[update_scope_local_id] <> @sync_scope_local_id) then case when ([side].[local_update_peer_key] > @sync_scope_restore_count) then @sync_scope_restore_count else [side].[local_update_peer_key] end else [side].[scope_update_peer_key] end as sync_update_peer_key, case when ([side].[create_scope_local_id] is null or [side].[create_scope_local_id] <> @sync_scope_local_id) then [side].[local_create_peer_timestamp] else [side].[scope_create_peer_timestamp] end as sync_create_peer_timestamp, case when ([side].[create_scope_local_id] is null or [side].[create_scope_local_id] <> @sync_scope_local_id) then case when ([side].[local_create_peer_key] > @sync_scope_restore_count) then @sync_scope_restore_count else [side].[local_create_peer_key] end else [side].[scope_create_peer_key] end as sync_create_peer_key from [RedeemCodes] [base] right join [RedeemCodes_tracking] [side] on [base].[Id] = [side].[Id] WHERE [side].[Id] = @P_1
END
